def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # If we're at the end of the line, we have one field
        if i == len(line):
            fields.append('')
            break

        # Check if field is quoted
        if i < len(line) and line[i] == '"':
            # Quoted field
            field = ''
            i += 1  # Skip opening quote

            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i == len(line):
                            fields.append(field)
                            break
                        elif line[i] == ',':
                            fields.append(field)
                            i += 1
                            # Continue to next field
                            break
                        else:
                            # Invalid: closing quote not followed by comma or end
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is invalid
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i < len(line) and line[i] == ',':
                i += 1

    return fields

